const items = $input.all();

// Generic column detection, edit hints if a different file uses different headers
const ORG_KEY_HINTS = ['company name', 'company', 'organization', 'organisation', 'employer'];
const ROLE_KEY_HINTS = ['job title', 'person job title', 'title', 'position', 'role'];
const FORENAME_KEY_HINTS = ['person forename', 'forename', 'first name'];
const SURNAME_KEY_HINTS = ['person surname', 'surname', 'last name'];

function findKey(obj, hints) {
  const keys = Object.keys(obj);
  for (const hint of hints) {
    const found = keys.find(k => k.toLowerCase().trim() === hint);
    if (found) return found;
  }
  for (const hint of hints) {
    const found = keys.find(k => k.toLowerCase().includes(hint));
    if (found) return found;
  }
  return null;
}

if (items.length === 0) return [];

const sample = items[0].json;
const orgKey = findKey(sample, ORG_KEY_HINTS);
const roleKey = findKey(sample, ROLE_KEY_HINTS);
const forenameKey = findKey(sample, FORENAME_KEY_HINTS);
const surnameKey = findKey(sample, SURNAME_KEY_HINTS);

if (!orgKey) {
  throw new Error(`Could not detect an organization column. Headers found: ${Object.keys(sample).join(', ')}. Edit ORG_KEY_HINTS at the top of this node.`);
}

const groups = {};

for (const item of items) {
  const row = item.json;
  const orgRaw = (row[orgKey] || '').toString().trim();
  if (!orgRaw) continue; // no organization, nothing to attach this row to

  const fname = forenameKey ? (row[forenameKey] || '').toString().trim() : '';
  const sname = surnameKey ? (row[surnameKey] || '').toString().trim() : '';
  const roleText = roleKey ? (row[roleKey] || '').toString().trim() : '';
  const orgNorm = orgRaw.toLowerCase();
  const nameText = `${fname} ${sname}`.trim();

  if (!groups[orgNorm]) groups[orgNorm] = { organization: orgRaw, candidates: [], seen: new Set() };

  // same person, same title at this organization (just a different project row), not a real second candidate
  // for unnamed rows, this also collapses every anonymous role at the same org into one generic entry
  const dedupeKey = `${nameText.toLowerCase()}|${roleText.toLowerCase()}`;
  if (groups[orgNorm].seen.has(dedupeKey)) continue;
  groups[orgNorm].seen.add(dedupeKey);

  groups[orgNorm].candidates.push({
    role: roleText || 'Unknown',
    name: nameText,
    row
  });
}

const output = [];

for (const org of Object.values(groups)) {
  const named = org.candidates.filter(c => c.name);
  const unnamed = org.candidates.filter(c => !c.name);

  // a named person always wins over a generic/unnamed entry, nothing to compare there
  const finalCandidates = named.length > 0 ? named : unnamed;

  for (const c of finalCandidates) {
    c.row['Contact Type'] = c.name ? 'Named' : 'Generic (no named contact)';
  }

  output.push({ json: { organization: org.organization, candidates: finalCandidates } });
}

return output;

const items = $input.all();
const config = $('Set Workflow Parameters').first().json;
const out = [];

for (const item of items) {
  const candidates = item.json.candidates;
  const organization = item.json.organization;

  const promptText = candidates
    .map((c, i) => `${i + 1}. ${c.role}${c.name ? ' - ' + c.name : ''}`)
    .join('\n');

  const requestBody = {
    model: config.aiModel,
    max_tokens: 20,
    messages: [
      {
        role: 'user',
        content: `You are identifying the single most senior or significant contact at "${organization}" for the purpose of business outreach. Here is the list of people and their roles:\n\n${promptText}\n\nRespond with only the number of the one most senior or significant contact. Reply with a number only, nothing else.`
      }
    ]
  };

  out.push({ json: { organization, candidates, requestBody } });
}

return out;

const responseJson = $json;

// OpenRouter uses the OpenAI-compatible chat completions response shape
let text = '';
if (Array.isArray(responseJson.choices) && responseJson.choices[0] && responseJson.choices[0].message) {
  text = responseJson.choices[0].message.content || '';
}

const match = text.match(/\d+/);
const upstream = $('Prepare AI Prompt').item.json;
const candidates = upstream.candidates;

let idx = match ? parseInt(match[0], 10) - 1 : 0;
if (idx < 0 || idx >= candidates.length) idx = 0;

return { json: candidates[idx].row };

const items = $input.all(); // one item per organization, from Group Rows By Organization

const totalOrgs = items.length;
let totalCandidateRows = 0;
let orgsNeedingAI = 0;
let orgsSingleCandidate = 0;
let orgsGenericOnly = 0;
const multiList = [];

for (const item of items) {
  const candidates = item.json.candidates;
  totalCandidateRows += candidates.length;

  const hasNamedContact = candidates.some(c => c.name);
  if (!hasNamedContact) orgsGenericOnly++;

  if (candidates.length > 1) {
    orgsNeedingAI++;
    multiList.push({ organization: item.json.organization, candidateCount: candidates.length });
  } else {
    orgsSingleCandidate++;
  }
}

multiList.sort((a, b) => b.candidateCount - a.candidateCount);

const report = {
  organizationsFound: totalOrgs,
  totalEligibleContactRows: totalCandidateRows,
  organizationsResolvedDirectly: orgsSingleCandidate,
  organizationsSentToAIForRanking: orgsNeedingAI,
  organizationsWithNoNamedContact: orgsGenericOnly,
  finalContactsProduced: totalOrgs,
  topOrganizationsByCandidateCount: multiList.slice(0, 20)
};

return [{ json: report }];
